            "பெற்றோர் வழிகாட்டல் என்பது குழந்தைகள் நல்ல மதிப்பெண்களைப் பெறுவதற்கோ அல்லது தேர்வுகளில் தேர்ச்சி பெறுவதற்கோ மட்டுமே உதவுவது அல்ல; மாறாக அவர்கள் தங்கள் சொந்த ஆர்வங்களை ஆராயவும், புதிய யோசனைகளை வெளிப்படுத்தவும், தவறுகளிலிருந்து கற்றுக்கொள்ளவும், தங்களுக்குப் பிடித்ததை ரசித்துச் செய்யவும் தன்னம்பிக்கை கொண்ட ஒரு சூழலை உருவாக்குவதாகும்.",
